package techguns.compat.fusion;

import net.minecraft.network.chat.Component;
import net.minecraft.server.packs.PackType;
import net.minecraft.server.packs.repository.Pack;
import net.minecraft.server.packs.repository.PackSource;
import net.neoforged.bus.api.IEventBus;
import net.neoforged.fml.ModList;
import net.neoforged.neoforge.event.AddPackFindersEvent;
import techguns.TGIds;

/**
 * Connected textures (Techguns 2 used the CTM mod) through Fusion: the built-in resource pack {@value #PACK_PATH}
 * (generated by {@code LegacyConnectedTextureProvider}) holds Fusion sheets for the blocks Techguns 2 connected, and
 * is only added, always on, when Fusion is installed. Without Fusion the plain textures stay.
 */
public final class FusionTextures {
    public static final String MOD_ID = "fusion";
    /** Path of the pack inside the mod's resources. */
    public static final String PACK_PATH = "resourcepacks/fusion";

    private FusionTextures() {
    }

    public static void init(IEventBus modBus) {
        modBus.addListener(FusionTextures::addPack);
    }

    private static void addPack(AddPackFindersEvent event) {
        if (event.getPackType() == PackType.CLIENT_RESOURCES && ModList.get().isLoaded(MOD_ID)) {
            event.addPackFinders(TGIds.id(PACK_PATH), PackType.CLIENT_RESOURCES, Component.translatable("pack.techguns.fusion"),
                    PackSource.BUILT_IN, true, Pack.Position.TOP);
        }
    }
}
